import 'likerts.dart';

List<String>? _selected(dynamic answer) {if(answer is String)return [answer];if(answer is List)return answer.whereType<String>().toList();if(answer is Map&&answer['selected'] is List)return (answer['selected'] as List).whereType<String>().toList();return null;}
bool _answered(dynamic answer){if(answer==null)return false;if(answer is String)return answer.trim().isNotEmpty;if(answer is List)return answer.isNotEmpty;if(answer is Map)return _selected(answer)?.isNotEmpty==true;if(answer is num)return true;return false;}
bool conditionMatches(VisibilityCondition condition,dynamic answer){switch(condition.operator){case 'answered':return _answered(answer);case 'not_answered':return !_answered(answer);case 'equals':case 'not_equals':if(answer==null)return false;final selected=_selected(answer);final actual=selected?.length==1?selected!.first:answer;final equal=actual==condition.value;return condition.operator=='equals'?equal:!equal;case 'includes':case 'not_includes':if(answer==null)return false;final included=_selected(answer)?.contains(condition.value)==true;return condition.operator=='includes'?included:!included;default:throw const FormatException('Unsupported visibility operator');}}
Set<String> visibleQuestionIds(List<Question> questions,Map<String,dynamic> answers){final byId={for(final q in questions)q.id:q};final memo=<String,bool>{};final active=<String>{};bool visible(Question q){if(memo.containsKey(q.id))return memo[q.id]!;if(!active.add(q.id))throw const FormatException('Conditional visibility cycle');final condition=q.visibleWhen;final result=condition==null?true:conditionMatches(condition,visible(byId[condition.questionId]??(throw const FormatException('Unknown visibility question')))?answers[condition.questionId]:null);active.remove(q.id);memo[q.id]=result;return result;}return questions.where(visible).map((q)=>q.id).toSet();}
Map<String,dynamic> visibleAnswers(List<Question> questions,Map<String,dynamic> answers){final visible=visibleQuestionIds(questions,answers);return Map.fromEntries(answers.entries.where((entry)=>visible.contains(entry.key)));}
